<?php
declare(strict_types=1);
$root=dirname(__DIR__);$src=implode("\n", array_map('file_get_contents', array_merge([$root.'/includes/class-sn-file-transfer.php'], glob($root.'/includes/class-sn-file-transfer-part-*.php'))));$crypto=file_get_contents($root.'/includes/class-sn-communication-crypto.php');$js=file_get_contents($root.'/assets/js/file-transfer.js');$fails=[];$checks=0;
