fta(str_contains($src,"claims['version']")&&str_contains($src,'version=version+1'),'Revocation invalidates previously issued grants.');
fta(str_contains($src,'recipient_ids')&&str_contains($src,'conversation_id'),'Both individual and authorized-group recipient modes exist.');
fta(str_contains($src,'MAX_RECIPIENTS = 256'),'Group transfer fan-out is bounded.');
fta(str_contains($src,'daily_transfer_bytes')&&str_contains($src,'daily_transfer_volume_exceeded'),'Daily volume has a transparent configurable ceiling.');
fta(str_contains($src,'transfer_relationship_changed'),'Changed relationship/verification state blocks later access.');
